package com.tecsup.cita.model;import jakarta.persistence.*;import jakarta.validation.constraints.*;import java.time.LocalDate;import java.time.LocalTime;
@Entity@Table(name="cita")public class Cita{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="id_cita")private Long id;@NotNull@Column(nullable=false)private LocalDate fecha;@NotNull@Column(nullable=false)private LocalTime hora;@NotNull@Column(name="id_paciente",nullable=false)private Long idPaciente;@NotNull@Column(name="id_medico",nullable=false)private Long idMedico;@Size(max=300)private String motivo;@Column(nullable=false,length=20)private String estado="PROGRAMADA";public Long getId(){return id;}public LocalDate getFecha(){return fecha;}public void setFecha(LocalDate x){fecha=x;}public LocalTime getHora(){return hora;}public void setHora(LocalTime x){hora=x;}public Long getIdPaciente(){return idPaciente;}public void setIdPaciente(Long x){idPaciente=x;}public Long getIdMedico(){return idMedico;}public void setIdMedico(Long x){idMedico=x;}public String getMotivo(){return motivo;}public void setMotivo(String x){motivo=x;}public String getEstado(){return estado;}public void setEstado(String x){estado=x;}}
